class BillingServiceServicer(billing_pb2_grpc.BillingServiceServicer):
    async def GetBillingInvoice(self, request, context):
        caller = await authenticate_grpc_metadata(context)
        async with AsyncSessionLocal() as session:
            invoice = await session.get(Invoice, request.invoice_id)
            if not invoice:
                await context.abort(grpc.StatusCode.NOT_FOUND, "Invoice not found")
            if invoice.tenant_id != caller.tenant_id:
                await context.abort(grpc.StatusCode.PERMISSION_DENIED, "Access denied to invoice")
            return billing_pb2.InvoiceResponse(
                invoice_id=invoice.id,
                amount_cents=invoice.amount_cents,
                pdf_url=invoice.pdf_url
            )
